use std.io

case_0 :: fn () -> i32 {
    value := 2
    hit := 0

    on value == 2 => {
        on {
            value == 1 => hit = 1
            else => hit = 2
        }
    }

    prn($"hit {hit}")
    return hit
}

use std.io

read :: fn (value: ?u8) -> u8 {
    return on value {
        byte => {
            copied : u8 = byte
            return copied
        }
        else => {
            return 0
        }
    }
}

case_1 :: fn () -> i32 {
    result := read('x')
    prn($"{result}")
    return result.as(i32)
}

case_2 :: fn () -> i32 {
    result := 0

    on yes {
        yes => {
            on yes => {
                result = 42
            }
        }
    }

    return result - 42
}

main :: fn () {
    prn("begin 062-run-llvm-nested-on-branch")
    result_0 := case_0()
    assert result_0 == 2
    prn("pass 062-run-llvm-nested-on-branch")
    prn("begin 129-run-on-expression-return-branches")
    result_1 := case_1()
    assert result_1 == 120
    prn("pass 129-run-on-expression-return-branches")
    prn("begin 252-run-nested-partial-on-statement")
    result_2 := case_2()
    assert result_2 == 0
    prn("pass 252-run-nested-partial-on-statement")
    prn("completed 3 cases")
}
